import { Router } from 'express';
import { getConfigManager } from '../services/ConfigManager';
import type { TelemetryService } from '../services/TelemetryService';
import type { Account } from '../types/account';
import { createLogger } from '../utils/logger';
import { parseInstallRef } from '../utils/installRef';

const log = createLogger('AccountRoutes');

export const createAccountRouter = (telemetry?: TelemetryService) => {
  const router = Router();
  router.get('/account', (_req, res) => {
    const config = getConfigManager();
    const account: Account = {
      isAuthenticated: config.isAuthenticated(),
      email: config.getEmail(),
      name: config.getDisplayName(),
      userId: config.getUserId(),
    };
    res.json(account);
  });

  router.post('/auth/store', (req, res) => {
    const { email, token, refreshToken, userId, installRef } = req.body ?? {};
    if (!email || !token) {
      return res.status(400).json({ error: 'Missing email or token' });
    }
    try {
      const config = getConfigManager();
      config.setAuth(token, email, refreshToken, userId);
      const carriedInstallRef = parseInstallRef(installRef);
      if (carriedInstallRef) {
        config.completeInstallRefSignIn(carriedInstallRef, config.getUserId());
      }
    } catch {
      return res
        .status(500)
        .json({ error: 'Failed to store auth credentials' });
    }
    telemetry?.identifyUser();
    telemetry?.reportInstallRefActivations();
    log.info(`Stored auth for ${email} via browser OAuth`);
    res.json({ success: true });
  });

  router.post('/auth/logout', (_req, res) => {
    try {
      getConfigManager().clearAuth();
    } catch (error) {
      log.warn('Logout failed', error);
      return res.status(500).json({ error: 'Failed to log out' });
    }
    log.info('Cleared auth via logout');
    res.json({ success: true });
  });

  return router;
};
